 * A token bucket that holds `capacity` tokens, refills `refill` tokens for
 * every `per` ticks that pass, and keeps one independent state per key.
 * Tokens are tracked in units of `per` (a bucket holding a whole token holds
 * at least `per` units) so that partial refill periods never need rounding.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  advance(key, tick) {
    const state = this.states.get(key)
    if (!state) {
      this.states.set(key, { lastTick: tick, unitsNum: this.capacity * this.per })
      return
    }
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      const capNum = this.capacity * this.per
      state.unitsNum += this.refill * elapsed
      if (state.unitsNum > capNum) state.unitsNum = capNum
      state.lastTick = tick
    }
  }

  allow(key) {
    return this.states.get(key).unitsNum >= this.per
  }

  record(key) {
    this.states.get(key).unitsNum -= this.per
  }
}

