  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let ticks = this.states.get(key)
    if (!ticks) {
      ticks = []
      this.states.set(key, ticks)
    }
    const threshold = tick - this.span
    while (ticks.length > 0 && ticks[0] <= threshold) ticks.shift()
  }

  allow(key) {
    return BigInt(this.states.get(key).length) < this.limit
  }

  record(key, tick) {
    this.states.get(key).push(tick)
  }
}
