  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  let firstEventSeen = false
  let lastTick = null

  const events = []
  const keyOrder = []
  const keySeen = new Set()

  for (let index = 0; index < lines.length; index++) {
    const trimmed = lines[index].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const fields = trimmed.split(/\s+/)
    const directive = fields[0]
    const rest = fields.slice(1)

    try {
      switch (directive) {
        case 'bucket':
          declareBucket(rest)
          break
        case 'window':
          declareWindow(rest)
          break
        case 'route':
          declareRoute(rest)
          break
        case 'event':
          recordEvent(rest)
          break
        default:
          throw new CliError(`unknown directive ${directive}`)
      }
    } catch (error) {
      if (error instanceof CliError) {
        throw new CliError(`line ${index + 1}: ${error.message}`)
      }
      throw error
    }
  }

  return { events, keyOrder }

  function requireNoEventsYet() {
    if (firstEventSeen) throw new CliError('declarations must come before the first event')
  }

  function declareBucket(rest) {
    if (rest.length !== 4) throw new CliError('expected bucket <name> <capacity> <refill> <per>')
    requireNoEventsYet()
    const [name, capacityStr, refillStr, perStr] = rest
    if (!isToken(name)) throw new CliError(`invalid policy name ${name}`)
    const capacity = parseIntField(capacityStr, 'capacity', 1n)
    const refill = parseIntField(refillStr, 'refill', 0n)
    const per = parseIntField(perStr, 'per', 1n)
    if (policies.has(name)) throw new CliError(`policy ${name} is declared twice`)
    policies.set(name, new TokenBucket(capacity, refill, per))
  }

  function declareWindow(rest) {
    if (rest.length !== 3) throw new CliError('expected window <name> <limit> <span>')
    requireNoEventsYet()
    const [name, limitStr, spanStr] = rest
    if (!isToken(name)) throw new CliError(`invalid policy name ${name}`)
    const limit = parseIntField(limitStr, 'limit', 0n)
    const span = parseIntField(spanStr, 'span', 1n)
    if (policies.has(name)) throw new CliError(`policy ${name} is declared twice`)
    policies.set(name, new SlidingWindow(limit, span))
  }

  function declareRoute(rest) {
    if (rest.length < 2) throw new CliError('expected route <prefix> <policy>...')
    requireNoEventsYet()
    const [prefix, ...names] = rest
    if (!isToken(prefix)) throw new CliError(`invalid route prefix ${prefix}`)
    const routePolicies = []
    for (const name of names) {
      const instance = policies.get(name)
      if (!instance) throw new CliError(`unknown policy ${name}`)
      routePolicies.push({ name, instance })
    }
    if (routePrefixes.has(prefix)) throw new CliError(`prefix ${prefix} is routed twice`)
    routePrefixes.add(prefix)
    routes.push({ prefix, policies: routePolicies })
  }

  function recordEvent(rest) {
    if (rest.length !== 2) throw new CliError('expected event <tick> <key>')
    const [tickStr, keyStr] = rest
    const tick = parseIntField(tickStr, 'tick', 0n)
    if (!isToken(keyStr)) throw new CliError(`invalid key ${keyStr}`)
    if (lastTick !== null && tick < lastTick) {
      throw new CliError(`tick ${tick} is before tick ${lastTick}`)
    }
    firstEventSeen = true
    lastTick = tick

    if (!keySeen.has(keyStr)) {
      keySeen.add(keyStr)
      keyOrder.push(keyStr)
    }

    let route = null
    for (const candidate of routes) {
      if (keyStr.startsWith(candidate.prefix)) {
        if (!route || candidate.prefix.length > route.prefix.length) route = candidate
      }
    }

    let allowed = true
    let denyPolicy = null
    if (route) {
      for (const { instance } of route.policies) instance.advance(keyStr, tick)
      for (const { name, instance } of route.policies) {
        if (!instance.allow(keyStr)) {
          allowed = false
          denyPolicy = name
          break
        }
      }
      if (allowed) {
        for (const { instance } of route.policies) instance.record(keyStr, tick)
      }
    }

    events.push({ tick, key: keyStr, allowed, denyPolicy })
  }
}
