  const lines = result.events.map(({ tick, key, allowed, denyPolicy }) =>
    allowed ? `${tick} ${key} allow` : `${tick} ${key} deny ${denyPolicy}`
  )
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
